/**
 * Draws the blog's illustrations as real .svg files in public/blog/<slug>/.
 *
 * WHY FILES AND NOT INLINE SVG: Google Images only indexes an image it can
 * fetch at its own URL. Inline <svg> in the page markup is invisible to it —
 * it is markup, not a file. Every illustration here is therefore written to
 * disk and referenced from the post with <img src> + alt, which is also what
 * lets the alt text do its job in image search.
 *
 * WHY DRAWN IN CODE AND NOT GENERATED BY A PICTURE MODEL: these are charts and
 * diagrams carrying the article's own numbers. They cost nothing to produce,
 * stay sharp at any size, weigh a few kilobytes, need no external service or
 * API key, and — unlike a generated photograph — they cannot quietly invent a
 * statistic that is not in the text.
 *
 * ADDING IMAGES TO A NEW POST
 *   1. Append entries to SPECS below: slug, name, heading and the data.
 *   2. Run `npm run blog:images`.
 *   3. Reference each one from the post body with an `image` block, giving a
 *      real alt sentence (see src/lib/blog.ts).
 * `npm run blog:check-images` fails the build if a post has fewer than four
 * images, an image has no alt text, or a referenced file is missing.
 *
 * FONTS: an SVG loaded through <img> cannot fetch a web font, so everything
 * here uses the system stack. That is why text is wrapped by this script
 * rather than by the browser — SVG has no automatic line breaking.
 */

import { mkdirSync, writeFileSync, readdirSync, rmSync, existsSync } from "node:fs";
import { join } from "node:path";

const OUT_ROOT = join("public", "blog");
const SIZES_FILE = join("src", "content", "blog-image-sizes.json");
const W = 960;

/**
 * The brand palette, as hex.
 *
 * globals.css states these in oklch, which is right for CSS but not safe in a
 * standalone SVG — a presentation attribute is not guaranteed to parse a
 * modern colour function, and an image that renders black in one browser is
 * worse than one that is a shade off. These are the exact sRGB conversions of
 * the --background/--foreground/--primary/... tokens; regenerate them if the
 * theme changes.
 */
const C = {
  ink: "#171923",
  inkSoft: "#5b5b67",
  border: "#e1e0db",
  card: "#ffffff",
  wash: "#f8f7f2",
  primary: "#7834e8",
  primarySoft: "#f1eafd",
  success: "#00945e",
  successSoft: "#e3f5ed",
  warning: "#e18600",
  warningSoft: "#fdf0dc",
  info: "#006ee1",
  danger: "#e7000b",
  dangerSoft: "#fdeaea",
};

const TONES = {
  primary: { fg: C.primary, bg: C.primarySoft },
  success: { fg: C.success, bg: C.successSoft },
  warning: { fg: C.warning, bg: C.warningSoft },
  info: { fg: C.info, bg: C.primarySoft },
  danger: { fg: C.danger, bg: C.dangerSoft },
  neutral: { fg: C.inkSoft, bg: C.wash },
};
const tone = (name) => TONES[name] ?? TONES.primary;

const FONT =
  "ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif";

const esc = (s) =>
  String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

/**
 * Greedy word wrap. `width` is the box in px and `size` the font size; the
 * 0.52 factor is the average glyph width of the system stack at normal
 * weight, measured against the longest lines in these specs. Erring narrow is
 * deliberate — a line that wraps early looks fine, one that overflows the card
 * does not.
 */
function wrap(text, width, size, factor = 0.52) {
  const max = Math.max(8, Math.floor(width / (size * factor)));
  const lines = [];
  let line = "";
  for (const word of String(text).split(/\s+/)) {
    const next = line ? `${line} ${word}` : word;
    if (next.length > max && line) {
      lines.push(line);
      line = word;
    } else {
      line = next;
    }
  }
  if (line) lines.push(line);
  return lines;
}

/** Multi-line <text>, returning the markup and the height it consumed. */
function textBlock(x, y, lines, { size, weight = 400, fill = C.ink, lh = 1.4 }) {
  const step = size * lh;
  const body = lines
    .map(
      (l, i) =>
        `<text x="${x}" y="${(y + size * 0.82 + i * step).toFixed(1)}" font-size="${size}" font-weight="${weight}" fill="${fill}">${esc(l)}</text>`,
    )
    .join("");
  return { svg: body, height: lines.length * step };
}

const tick = (x, y, color) =>
  `<circle cx="${x + 9}" cy="${y + 9}" r="9" fill="${color}" opacity="0.14"/><path d="M${x + 5} ${y + 9.5} l2.8 2.8 L${x + 13.4} ${y + 5.6}" fill="none" stroke="${color}" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>`;

const cross = (x, y, color) =>
  `<circle cx="${x + 9}" cy="${y + 9}" r="9" fill="${color}" opacity="0.14"/><path d="M${x + 5.8} ${y + 5.8} l6.4 6.4 M${x + 12.2} ${y + 5.8} l-6.4 6.4" fill="none" stroke="${color}" stroke-width="2.2" stroke-linecap="round"/>`;

const dot = (x, y, color) => `<circle cx="${x + 9}" cy="${y + 9}" r="3.4" fill="${color}"/>`;

const mark = (kind, x, y, color) =>
  kind === "cross" ? cross(x, y, color) : kind === "dot" ? dot(x, y, color) : tick(x, y, color);

/* ------------------------------------------------------------------ layouts */

const PAD = 40;
const HEAD_Y = 36;

/** Title at the top of every image, plus the y the body starts at. */
function header(heading, sub) {
  const titleLines = wrap(heading, W - PAD * 2 - 10, 27, 0.55);
  const t = textBlock(PAD, HEAD_Y, titleLines, { size: 27, weight: 700 });
  let y = HEAD_Y + t.height + 6;
  let svg = `<rect x="${PAD}" y="${HEAD_Y - 18}" width="46" height="5" rx="2.5" fill="${C.primary}"/>${t.svg}`;
  if (sub) {
    const s = textBlock(PAD, y, wrap(sub, W - PAD * 2, 16), {
      size: 16,
      fill: C.inkSoft,
    });
    svg += s.svg;
    y += s.height + 4;
  }
  return { svg, y: y + 18 };
}

function panels(spec) {
  const list = spec.panels;
  const cols = spec.cols ?? Math.min(list.length, 3);
  const rows = Math.ceil(list.length / cols);
  const gap = 18;
  const cw = (W - PAD * 2 - gap * (cols - 1)) / cols;

  const h = header(spec.heading, spec.sub);
  // Lay every card out first so one tall card sets the row height and the
  // grid stays aligned instead of ragged.
  const laid = list.map((p) => {
    const inner = cw - 36;
    let y = 0;
    let svg = "";
    const labelLines = wrap(p.label, inner - 4, 19, 0.56);
    const lab = textBlock(18, y + 16, labelLines, { size: 19, weight: 700 });
    svg += lab.svg;
    y += 16 + lab.height;
    if (p.tagline) {
      const tg = textBlock(18, y, wrap(p.tagline.toUpperCase(), inner, 11, 0.62), {
        size: 11,
        weight: 700,
        fill: tone(p.tone).fg,
      });
      svg += tg.svg;
      y += tg.height;
    }
    y += 10;
    for (const it of p.items) {
      const txt = typeof it === "string" ? it : it.text;
      const m = typeof it === "string" ? "dot" : (it.mark ?? "dot");
      const lines = wrap(txt, inner - 28, 14.5);
      svg += mark(m, 18, y + 1, tone(p.tone).fg);
      const tb = textBlock(18 + 27, y, lines, { size: 14.5, fill: C.ink, lh: 1.42 });
      svg += tb.svg;
      y += Math.max(tb.height, 22) + 7;
    }
    return { svg, height: y + 14 };
  });

  const rowH = [];
  for (let r = 0; r < rows; r++) {
    rowH.push(
      Math.max(...laid.slice(r * cols, (r + 1) * cols).map((l) => l.height)),
    );
  }

  let body = "";
  laid.forEach((card, i) => {
    const r = Math.floor(i / cols);
    const c = i % cols;
    const x = PAD + c * (cw + gap);
    const y = h.y + rowH.slice(0, r).reduce((a, b) => a + b + gap, 0);
    const t = tone(list[i].tone);
    body += `<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><rect x="0" y="0" width="${cw.toFixed(1)}" height="${rowH[r]}" rx="18" fill="${C.card}" stroke="${C.border}"/><rect x="0" y="0" width="${cw.toFixed(1)}" height="4" rx="2" fill="${t.fg}"/>${card.svg}</g>`;
  });

  const height = h.y + rowH.reduce((a, b) => a + b + gap, 0) - gap + PAD;
  return { body: h.svg + body, height };
}

function bars(spec) {
  const h = header(spec.heading, spec.sub);
  const max = spec.max ?? Math.max(...spec.bars.map((b) => b.value));
  const labelW = 220;
  const trackX = PAD + labelW;
  const trackW = W - PAD - trackX - 92;
  let y = h.y;
  let body = "";
  for (const b of spec.bars) {
    const t = tone(b.tone);
    const w = max > 0 ? Math.max(3, (b.value / max) * trackW) : 3;
    const lines = wrap(b.label, labelW - 14, 14.5);
    const tb = textBlock(PAD, y + 2, lines, { size: 14.5, weight: 600 });
    body += tb.svg;
    body += `<rect x="${trackX}" y="${y + 4}" width="${trackW}" height="26" rx="13" fill="${C.wash}"/>`;
    body += `<rect x="${trackX}" y="${y + 4}" width="${w.toFixed(1)}" height="26" rx="13" fill="${t.fg}"/>`;
    body += `<text x="${trackX + trackW + 14}" y="${y + 23}" font-size="16" font-weight="700" fill="${t.fg}">${esc(b.display ?? String(b.value))}</text>`;
    y += Math.max(tb.height, 34) + 12;
  }
  if (spec.note) {
    const n = textBlock(PAD, y + 6, wrap(spec.note, W - PAD * 2, 14), {
      size: 14,
      fill: C.inkSoft,
    });
    body += n.svg;
    y += n.height + 6;
  }
  return { body: h.svg + body, height: y + PAD };
}

function checklist(spec) {
  const h = header(spec.heading, spec.sub);
  const gap = 18;
  const cw = (W - PAD * 2 - gap) / 2;
  const laid = spec.columns.map((col) => {
    const inner = cw - 36;
    let y = 0;
    let svg = "";
    const lab = textBlock(18, y + 16, wrap(col.label, inner, 18, 0.56), {
      size: 18,
      weight: 700,
      fill: tone(col.tone).fg,
    });
    svg += lab.svg;
    y += 16 + lab.height + 10;
    for (const it of col.items) {
      const lines = wrap(it, inner - 28, 14.5);
      svg += mark(col.mark, 18, y + 1, tone(col.tone).fg);
      const tb = textBlock(18 + 27, y, lines, { size: 14.5, lh: 1.42 });
      svg += tb.svg;
      y += Math.max(tb.height, 22) + 8;
    }
    return { svg, height: y + 14 };
  });
  const rowH = Math.max(...laid.map((l) => l.height));
  let body = "";
  laid.forEach((col, i) => {
    const t = tone(spec.columns[i].tone);
    body += `<g transform="translate(${PAD + i * (cw + gap)} ${h.y})"><rect x="0" y="0" width="${cw.toFixed(1)}" height="${rowH}" rx="18" fill="${t.bg}" stroke="${C.border}"/>${col.svg}</g>`;
  });
  return { body: h.svg + body, height: h.y + rowH + PAD };
}

function flow(spec) {
  const h = header(spec.heading, spec.sub);
  const cols = spec.cols ?? Math.min(spec.steps.length, 3);
  const rows = Math.ceil(spec.steps.length / cols);
  const gap = 16;
  const cw = (W - PAD * 2 - gap * (cols - 1)) / cols;
  const laid = spec.steps.map((s, i) => {
    const inner = cw - 32;
    let y = 46;
    let svg = `<circle cx="18" cy="20" r="15" fill="${tone(s.tone).fg}"/><text x="18" y="25.5" font-size="14" font-weight="700" fill="#ffffff" text-anchor="middle">${i + 1}</text>`;
    const lab = textBlock(16, y, wrap(s.label, inner, 16, 0.55), {
      size: 16,
      weight: 700,
    });
    svg += lab.svg;
    y += lab.height + 2;
    if (s.detail) {
      const d = textBlock(16, y, wrap(s.detail, inner, 13.5), {
        size: 13.5,
        fill: C.inkSoft,
        lh: 1.45,
      });
      svg += d.svg;
      y += d.height;
    }
    return { svg, height: y + 16 };
  });
  const rowH = [];
  for (let r = 0; r < rows; r++) {
    rowH.push(Math.max(...laid.slice(r * cols, (r + 1) * cols).map((l) => l.height)));
  }
  let body = "";
  laid.forEach((card, i) => {
    const r = Math.floor(i / cols);
    const c = i % cols;
    const x = PAD + c * (cw + gap);
    const y = h.y + rowH.slice(0, r).reduce((a, b) => a + b + gap + 10, 0);
    body += `<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><rect x="0" y="0" width="${cw.toFixed(1)}" height="${rowH[r]}" rx="16" fill="${C.card}" stroke="${C.border}"/>${card.svg}</g>`;
    // Arrow to the next card in the same row.
    if (c < cols - 1 && i < laid.length - 1) {
      const ax = x + cw + gap / 2;
      const ay = y + rowH[r] / 2;
      body += `<path d="M${ax - 4} ${ay - 5} l5 5 l-5 5" fill="none" stroke="${C.inkSoft}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/>`;
    }
  });
  const height = h.y + rowH.reduce((a, b) => a + b + gap + 10, 0) - gap - 10 + PAD;
  return { body: h.svg + body, height };
}

function rows(spec) {
  const h = header(spec.heading, spec.sub);
  let y = h.y;
  let body = "";
  const pickW = 230;
  const whenW = W - PAD * 2 - pickW - 50;
  spec.rows.forEach((r, i) => {
    const lines = wrap(r.when, whenW, 15);
    const tb = textBlock(PAD + 20, y + 14, lines, { size: 15, lh: 1.42 });
    const rowH = Math.max(tb.height + 28, 60);
    const t = tone(r.tone);
    body += `<rect x="${PAD}" y="${y}" width="${W - PAD * 2}" height="${rowH}" rx="${i === 0 || i === spec.rows.length - 1 ? 16 : 2}" fill="${i % 2 ? C.wash : C.card}" stroke="${C.border}"/>`;
    body += tb.svg;
    const pw = Math.min(pickW, r.pick.length * 9.4 + 46);
    const px = W - PAD - 20 - pw;
    body += `<rect x="${px.toFixed(1)}" y="${y + rowH / 2 - 16}" width="${pw.toFixed(1)}" height="32" rx="16" fill="${t.bg}"/>`;
    body += `<text x="${(px + pw / 2).toFixed(1)}" y="${y + rowH / 2 + 5.5}" font-size="14.5" font-weight="700" fill="${t.fg}" text-anchor="middle">${esc(r.pick)}</text>`;
    y += rowH + 8;
  });
  return { body: h.svg + body, height: y + PAD - 8 };
}

function stats(spec) {
  const h = header(spec.heading, spec.sub);
  const cols = spec.cols ?? Math.min(spec.stats.length, 3);
  const rows_ = Math.ceil(spec.stats.length / cols);
  const gap = 18;
  const cw = (W - PAD * 2 - gap * (cols - 1)) / cols;
  const laid = spec.stats.map((s) => {
    const inner = cw - 36;
    const valueLines = wrap(s.value, inner, 34, 0.6);
    const v = textBlock(18, 18, valueLines, {
      size: 34,
      weight: 800,
      fill: tone(s.tone).fg,
      lh: 1.15,
    });
    let y = 18 + v.height + 4;
    const lab = textBlock(18, y, wrap(s.label, inner, 14), {
      size: 14,
      fill: C.ink,
      lh: 1.4,
    });
    y += lab.height;
    let svg = v.svg + lab.svg;
    if (s.note) {
      const n = textBlock(18, y + 4, wrap(s.note, inner, 12.5), {
        size: 12.5,
        fill: C.inkSoft,
        lh: 1.4,
      });
      svg += n.svg;
      y += n.height + 4;
    }
    return { svg, height: y + 18 };
  });
  const rowH = [];
  for (let r = 0; r < rows_; r++) {
    rowH.push(Math.max(...laid.slice(r * cols, (r + 1) * cols).map((l) => l.height)));
  }
  let body = "";
  laid.forEach((card, i) => {
    const r = Math.floor(i / cols);
    const c = i % cols;
    const x = PAD + c * (cw + gap);
    const y = h.y + rowH.slice(0, r).reduce((a, b) => a + b + gap, 0);
    const t = tone(spec.stats[i].tone);
    body += `<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><rect x="0" y="0" width="${cw.toFixed(1)}" height="${rowH[r]}" rx="18" fill="${t.bg}" stroke="${C.border}"/>${card.svg}</g>`;
  });
  const height = h.y + rowH.reduce((a, b) => a + b + gap, 0) - gap + PAD;
  return { body: h.svg + body, height };
}

const LAYOUTS = { panels, bars, checklist, flow, rows, stats };

/* -------------------------------------------------------------------- render */

function render(spec) {
  const layout = LAYOUTS[spec.kind];
  if (!layout) throw new Error(`${spec.slug}/${spec.name}: unknown kind "${spec.kind}"`);
  const { body, height } = layout(spec);
  const H = Math.round(height + 34); // room for the footer line
  // The wordmark travels with the image. An illustration lifted into Google
  // Images or a WhatsApp forward then still says where it came from.
  const footer = `<text x="${W - PAD}" y="${H - 16}" font-size="12.5" font-weight="700" fill="${C.inkSoft}" text-anchor="end" opacity="0.75">ozzo.co.in</text>`;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" font-family="${FONT}"><title>${esc(spec.heading)}</title><rect width="${W}" height="${H}" rx="22" fill="${C.card}"/><rect x="0.5" y="0.5" width="${W - 1}" height="${H - 1}" rx="21.5" fill="none" stroke="${C.border}"/>${body}${footer}</svg>\n`;
  return { svg, height: H };
}

