/* ---------------------------------------------------------------------- main */

const bySlug = new Map();
for (const spec of SPECS) {
  if (!bySlug.has(spec.slug)) bySlug.set(spec.slug, []);
  bySlug.get(spec.slug).push(spec);
}

// Two images cannot share a name inside one post — the second would silently
// overwrite the first and one post would show the same picture twice.
for (const [slug, list] of bySlug) {
  const seen = new Set();
  for (const s of list) {
    if (seen.has(s.name)) {
      console.error(`✗ ${slug}: duplicate image name "${s.name}"`);
      process.exit(1);
    }
    seen.add(s.name);
  }
}

let written = 0;
let bytes = 0;
const sizes = {};
for (const [slug, list] of bySlug) {
  const dir = join(OUT_ROOT, slug);
  mkdirSync(dir, { recursive: true });
  const keep = new Set(list.map((s) => `${s.name}.svg`));
  // Drop files from a spec that was renamed or removed, so the directory can
  // never accumulate orphans that the post no longer references.
  if (existsSync(dir)) {
    for (const f of readdirSync(dir)) {
      if (f.endsWith(".svg") && !keep.has(f)) {
        rmSync(join(dir, f));
        console.log(`  removed orphan ${slug}/${f}`);
      }
    }
  }
  for (const spec of list) {
    const { svg, height } = render(spec);
    writeFileSync(join(dir, `${spec.name}.svg`), svg, "utf8");
    // The post body carries only src, alt and caption. Width and height come
    // from here, so the <img> reserves the right space on first paint and the
    // numbers can never drift away from the file they describe.
    sizes[`/blog/${slug}/${spec.name}.svg`] = { w: W, h: height };
    written++;
    bytes += Buffer.byteLength(svg);
  }
  console.log(`${slug} — ${list.length} images`);
}

writeFileSync(
  SIZES_FILE,
  `${JSON.stringify(
    Object.fromEntries(Object.keys(sizes).sort().map((k) => [k, sizes[k]])),
    null,
    2,
  )}
`,
  "utf8",
);

console.log(
  `\n✓ ${written} images in ${bySlug.size} posts, ${(bytes / 1024).toFixed(0)}KB total ` +
    `(avg ${(bytes / written / 1024).toFixed(1)}KB)\n`,
);
console.log(`  sizes written to ${SIZES_FILE}
`);
